window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0b69167224d1af10"]={"versions": [{"id": "FIG-0b69167224d1af10", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-2-Komponentendiagramm (Strukturdiagramm mit Schnittstellenbeziehungen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Abhängigkeit und Schnittstellenbereitstellung (<em>Provided Interface</em>) des Functional Clusters <code>Operating System Interface</code> (OSI) gegenüber anderen Funktionsclustern der AUTOSAR Adaptive Platform (AP) gemäß Kapitel 5.1.</li>\n<li><strong>Architektur-Einordnung:</strong> In der AUTOSAR Adaptive Architektur kapselt das <code>Operating System Interface</code> das zugrundeliegende POSIX-Betriebssystem (PSE51-Subset). Das Diagramm definiert den normativen Bereitstellungspfad für Betriebssystem-Primitive an den <code>Communication Management daemon-based</code>-Cluster.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster» Operating System Interface</code> (Provider): Der funktionale Plattform-Cluster, der OS-Abstraktionen und Systemressourcen bereitstellt.</li>\n<li><code>«aapFunctionalCluster» Communication Management daemon-based</code> (Client): Die daemon-basierte Implementierungsvariante des <code>ara::com</code>-Stacks, welche Hintergrundprozesse für IPC-, SOME/IP- oder Netzwerk-Routing betreibt.</li>\n<li><code>«aapAPI, aapNativeInterface» OperatingSystemInterface</code>: Die typisierte, native C++- bzw. POSIX-basierte Programmierschnittstelle.</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Interface Realization</strong> (gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze): <code>Operating System Interface</code> implementiert und exponiert die Schnittstelle <code>OperatingSystemInterface</code>.</li>\n<li><strong>Usage Dependency</strong> (<code>«use»</code>, offene Pfeilspitze): <code>Communication Management daemon-based</code> konsumiert die Schnittstelle zur Laufzeit.</li>\n<li><strong>Kardinalität:</strong> 1:n-Architekturmuster (OSI stellt die Schnittstelle prinzipiell plattformweit bereit; hier normativ auf den Daemon-basierten Kommunikationscluster fokussiert).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Architektur- und Schnittstellenmodell; keine Sequenz- oder Zustandsübergänge abgebildet.</li>\n<li><strong>Laufzeit-Interaktion (impliziert durch SWS-Kontext Table 5.1):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Thread-Instanziierung:</strong> Der Kommunikations-Daemon ruft synchrone Fabrik-/Erzeugungsmethoden der Schnittstelle auf, um Worker-Threads für Event-Loops, Socket-Multiplexing (<code>epoll</code>/<code>poll</code>) und IPC-Dispatching zu generieren.</li>\n<li><strong>Thread-Kontrolle:</strong> Konfiguration von Scheduling-Parametern (z. B. <code>SCHED_FIFO</code>, <code>SCHED_RR</code>), Prioritäten und Thread-Affinitäten über die OS-Interface-APIs.</li>\n<li><strong>Synchronisation & Terminierung:</strong> Geordnetes Beenden und Joinen von Worker-Threads bei Shutdown- oder State-Management-Übergängen.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Für Stack-Entwickler (Communication Management):</strong></li>\n<li>Direkte, hardcodierte POSIX-Aufrufe (<code>pthread_create</code>, etc.) sind zu vermeiden; die Thread-Generierung und -Steuerung muss über die durch den OSI-Cluster vorgegebenen Abstraktionen erfolgen.</li>\n<li>Gewährleistung, dass Daemon-Threads deterministisch initialisiert und über das OS-Interface konfigurierbar bleiben (Stack-Größe, Thread-Name für Tracing/Debugging).</li>\n<li><strong>Für OS- & Plattform-Integratoren:</strong></li>\n<li>Implementierungspflicht: Der OSI-Cluster muss die geforderten Thread-Management-APIs konform zum konfigurierten POSIX-Profil (PSE51) exportieren.</li>\n<li>Privilegien & Capabilities: Der Communication-Daemon-Prozess benötigt ausreichende OS-Rechte (z. B. Setzen von Echtzeit-Prioritäten), die das OSI steuern und gegen Sicherheitsrichtlinien absichern muss.</li>\n</ul>"}, {"id": "FIG-0c4dda997ff779c5", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-2-Komponentendiagramm (Strukturdiagramm mit Schnittstellenbeziehungen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Abhängigkeit und Schnittstellenbereitstellung (<em>Provided Interface</em>) des Functional Clusters <code>Operating System Interface</code> (OSI) gegenüber anderen Funktionsclustern der AUTOSAR Adaptive Platform (AP) gemäß Kapitel 5.1.</li>\n<li><strong>Architektur-Einordnung:</strong> In der AUTOSAR Adaptive Architektur kapselt das <code>Operating System Interface</code> das zugrundeliegende POSIX-Betriebssystem (PSE51-Subset). Das Diagramm definiert den normativen Bereitstellungspfad für Betriebssystem-Primitive an den <code>Communication Management daemon-based</code>-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster» Operating System Interface</code> (Provider): Der funktionale Plattform-Cluster, der OS-Abstraktionen und Systemressourcen bereitstellt.</li>\n<li><code>«aapFunctionalCluster» Communication Management daemon-based</code> (Client): Die daemon-basierte Implementierungsvariante des <code>ara::com</code>-Stacks, welche Hintergrundprozesse für IPC-, SOME/IP- oder Netzwerk-Routing betreibt.</li>\n<li><code>«aapAPI, aapNativeInterface» OperatingSystemInterface</code>: Die typisierte, native C++- bzw. POSIX-basierte Programmierschnittstelle.</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Interface Realization</strong> (gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze): <code>Operating System Interface</code> implementiert und exponiert die Schnittstelle <code>OperatingSystemInterface</code>.</li>\n<li><strong>Usage Dependency</strong> (<code>«use»</code>, offene Pfeilspitze): <code>Communication Management daemon-based</code> konsumiert die Schnittstelle zur Laufzeit.</li>\n<li><strong>Kardinalität:</strong> 1:n-Architekturmuster (OSI stellt die Schnittstelle prinzipiell plattformweit bereit; hier normativ auf den Daemon-basierten Kommunikationscluster fokussiert).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Architektur- und Schnittstellenmodell; keine Sequenz- oder Zustandsübergänge abgebildet.</li>\n<li><strong>Laufzeit-Interaktion (impliziert durch SWS-Kontext Table 5.1):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Thread-Instanziierung:</strong> Der Kommunikations-Daemon ruft synchrone Fabrik-/Erzeugungsmethoden der Schnittstelle auf, um Worker-Threads für Event-Loops, Socket-Multiplexing (<code>epoll</code>/<code>poll</code>) und IPC-Dispatching zu generieren.</li>\n<li><strong>Thread-Kontrolle:</strong> Konfiguration von Scheduling-Parametern (z. B. <code>SCHED_FIFO</code>, <code>SCHED_RR</code>), Prioritäten und Thread-Affinitäten über die OS-Interface-APIs.</li>\n<li><strong>Synchronisation & Terminierung:</strong> Geordnetes Beenden und Joinen von Worker-Threads bei Shutdown- oder State-Management-Übergängen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Für Stack-Entwickler (Communication Management):</strong></li>\n<li>Direkte, hardcodierte POSIX-Aufrufe (<code>pthread_create</code>, etc.) sind zu vermeiden; die Thread-Generierung und -Steuerung muss über die durch den OSI-Cluster vorgegebenen Abstraktionen erfolgen.</li>\n<li>Gewährleistung, dass Daemon-Threads deterministisch initialisiert und über das OS-Interface konfigurierbar bleiben (Stack-Größe, Thread-Name für Tracing/Debugging).</li>\n<li><strong>Für OS- & Plattform-Integratoren:</strong></li>\n<li>Implementierungspflicht: Der OSI-Cluster muss die geforderten Thread-Management-APIs konform zum konfigurierten POSIX-Profil (PSE51) exportieren.</li>\n<li>Privilegien & Capabilities: Der Communication-Daemon-Prozess benötigt ausreichende OS-Rechte (z. B. Setzen von Echtzeit-Prioritäten), die das OSI steuern und gegen Sicherheitsrichtlinien absichern muss.</li>\n</ul>"}], "trans": [{"from": "FIG-0b69167224d1af10", "to": "FIG-0c4dda997ff779c5", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
